```typescript
export interface Candle {
  timestamp: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

export class VWAPCalculator {
  private period: number;
  private candles: Candle[] = [];
  private vwaps: number[] = [];

  constructor(period: number = 30) {
    this.period = period;
  }

  addCandle(candle: Candle): number | null {
    this.candles.push(candle);

    if (this.candles.length < this.period) {
      return null;
    }

    const startIdx = Math.max(0, this.candles.length - this.period);
    const window = this.candles.slice(startIdx);

    let cumulativePV = 0;
    let cumulativeVolume = 0;

    for (const c of window) {
      const typicalPrice = (c.high + c.low + c.close) / 3;
      cumulativePV += typicalPrice * c.volume;
      cumulativeVolume += c.volume;
    }

    const vwap = cumulativePV / cumulativeVolume;
    this.vwaps.push(vwap);
    return vwap;
  }

  getLatestVWAP(): number | null {
    return this.vwaps.length > 0 ? this.vwaps[this.vwaps.length - 1] : null;
  }

  getPreviousVWAP(): number | null {
    return this.vwaps.length > 1 ? this.vwaps[this.vwaps.length - 2] : null;
  }
}
```

**Create `src/strategy.ts` – Trading Strategy:**

```typescript
import { Candle, VWAPCalculator } from './vwap';

interface Position {
  type: 'LONG' | 'SHORT';
  entryPrice: number;
  entryTime: number;
  quantity: number;
}

interface Trade {
  type: 'LONG' | 'SHORT';
  entryPrice: number;
  exitPrice: number;
  entryTime: number;
  exitTime: number;
  pnlPercent: number;
  reason: 'PROFIT_TARGET' | 'STOP_LOSS' | 'SIGNAL';
}

export class VWAPStrategy {
  private vwapCalculator: VWAPCalculator;
  private position: Position | null = null;
  private trades: Trade[] = [];
  private gainTarget = 0.03; // 3% profit target
  private stopLoss = 0.01; // 1% stop loss

  constructor(vwapPeriod: number = 30) {
    this.vwapCalculator = new VWAPCalculator(vwapPeriod);
  }

  processCandle(candle: Candle): { action: 'BUY' | 'SELL' | 'HOLD'; reason?: string } {
    const currentVWAP = this.vwapCalculator.addCandle(candle);
    const previousVWAP = this.vwapCalculator.getPreviousVWAP();

    // Not enough data yet
    if (currentVWAP === null || previousVWAP === null) {
      return { action: 'HOLD', reason: 'Insufficient data for VWAP' };
    }

    // Check existing position for exit signals
    if (this.position) {
      const pnlPercent = this.calculatePnL(candle.close, this.position.entryPrice, this.position.type);

      // Exit on profit target
      if (pnlPercent >= this.gainTarget) {
        this.closeTrade(candle, 'PROFIT_TARGET', pnlPercent);
        return { action: 'SELL', reason: `3% profit target hit (${(pnlPercent * 100).toFixed(2)}%)` };
      }

      // Exit on stop loss
      if (pnlPercent <= -this.stopLoss) {
        this.closeTrade(candle, 'STOP_LOSS', pnlPercent);
        return { action: 'SELL', reason: `Stop loss hit (${(pnlPercent * 100).toFixed(2)}%)` };
      }
    }

    // Detect price crossover above VWAP
    const prevClose = this.candles.length > 1 ? this.candles[this.candles.length - 2].close : candle.close;

    if (
      prevClose <= previousVWAP &&
      candle.close > currentVWAP &&
      !this.position
    ) {
      this.position = {
        type: 'LONG',
        entryPrice: candle.close,
        entryTime: candle.timestamp,
        quantity: 1,
      };
      return { action: 'BUY', reason: `Price crossed above VWAP (${currentVWAP.toFixed(2)})` };
    }

    // Detect price crossover below VWAP
    if (
      prevClose >= previousVWAP &&
      candle.close < currentVWAP &&
      !this.position
    ) {
      this.position = {
        type: 'SHORT',
        entryPrice: candle.close,
        entryTime: candle.timestamp,
        quantity: 1,
      };
      return { action: 'BUY', reason: `Price crossed below VWAP (${currentVWAP.toFixed(2)}) - SHORT` };
    }

    return { action: 'HOLD' };
  }

  private candles: Candle[] = [];

  private calculatePnL(exitPrice: number, entryPrice: number, positionType: 'LONG' | 'SHORT'): number {
    if (positionType === 'LONG') {
      return (exitPrice - entryPrice) / entryPrice;
    } else {
      return (entryPrice - exitPrice) / entryPrice;
    }
  }

  private closeTrade(candle: Candle, reason: 'PROFIT_TARGET' | 'STOP_LOSS' | 'SIGNAL', pnlPercent: number) {
    if (this.position) {
      this.trades.push({
        type: this.position.type,
        entryPrice: this.position.entryPrice,
        exitPrice: candle.close,
        entryTime: this.position.entryTime,
        exitTime: candle.timestamp,
        pnlPercent,
        reason,
      });
      this.position = null;
    }
  }

  getStats() {
    if (this.trades.length === 0) {
      return { totalTrades: 0, winRate: 0, avgPnL: 0, maxDrawdown: 0 };
    }

    const winners = this.trades.filter((t) => t.pnlPercent > 0).length;
    const avgPnL = this.trades.reduce((sum, t) => sum + t.pnlPercent, 0) / this.trades.length;
    const maxDrawdown = Math.min(...this.trades.map((t) => t.pnlPercent));

    return {
      totalTrades: this.trades.length,
      winRate: winners / this.trades.length,
      avgPnL,
      maxDrawdown,
      trades: this.trades,
    };
  }
}
```

**Create `src/backtest.ts` – Backtester:**

```typescript
import { VWAPStrategy } from './strategy';
import { Candle } from './vwap';

export function runBacktest(candles: Candle[]) {
  const strategy = new VWAPStrategy(30);
  const signals: any[] = [];

  for (const candle of candles) {
    const signal = strategy.processCandle(candle);
    if (signal.action !== 'HOLD') {
      signals.push({
        timestamp: new Date(candle.timestamp).toISOString(),
        price: candle.close,
        action: signal.action,
        reason: signal.reason,
      });
    }
  }

  const stats = strategy.getStats();
  return { signals, stats };
}

